 \236\154\180\235\143\153\236\157\180 \236\149\132\235\139\140 \236\182\169\235\182\132\237\149\156 \236\139\156\234\176\132\236\157\180\236\167\128\235\167\140, \234\181\179\236\157\180 \236\157\180 \236\130\172\236\139\164\236\157\132 \235\176\157\237\152\128\236\132\156 \236\158\144\234\184\176\234\179\132\235\176\156 \236\157\152\236\167\128\235\165\188 \234\186\190\236\157\132 \237\149\132\236\154\148\235\138\148 \236\151\134\235\139\164\234\179\160 \237\140\144\235\139\168\237\150\136\234\184\176 \235\149\140\235\172\184\236\151\144 \235\179\184\236\157\184\236\157\180 \236\158\144\234\176\129\237\149\152\234\184\176 \236\160\132\234\185\140\236\167\132 \236\130\172\236\139\164\236\151\144 \235\140\128\237\149\180 \236\185\168\235\172\181\237\149\152\234\184\176\235\161\156 \235\139\168\236\155\144\235\147\164\236\151\144\234\178\140\235\143\132 \235\143\153\236\157\152\235\165\188 \234\181\172\237\150\136\236\138\181\235\139\136\235\139\164."
