L11_1 = "\235\172\188\235\179\145\236\158\144\235\166\172\236\157\152 \234\184\176\236\130\172, \236\151\144\235\166\172\236\150\180\236\138\164 \236\151\144\236\138\164\237\128\152\235\141\176\235\138\148 \236\157\152\236\167\128\234\176\128 \235\139\180\234\184\180 \236\132\177\236\136\152\235\161\156 \236\149\132\234\181\176\236\157\132 \237\154\140\235\179\181\237\149\152\234\179\160 \235\179\180\237\152\184\235\167\137\236\157\132 \235\182\128\236\151\172\237\149\152\235\138\148 \237\154\140\235\179\181\237\152\149 \236\167\128\236\155\144\234\176\128\236\158\133\235\139\136\235\139\164.\n\236\185\180\236\154\180\237\132\176\236\158\132\236\151\144\235\143\132 \235\182\136\234\181\172\237\149\152\234\179\160 \236\160\132\235\176\152\236\160\129\236\157\184 \236\178\180\235\160\165\237\143\137\234\176\128\235\138\148 \236\157\188\235\176\152\236\157\184\236\151\144 \235\175\184\236\185\152\236\167\128 \235\170\187\237\149\160 \236\160\149\235\143\132\236\157\184 \234\183\184\235\133\128\235\138\148 \234\176\129\236\132\177 \236\157\180\236\160\132\236\151\148 \236\153\184\236\182\156\235\143\132 \237\158\152\234\178\168\236\154\184 \236\160\149\235\143\132\235\161\156 \235\170\184\236\157\180 \235\182\136\237\142\184\237\150\136\236\151\136\236\138\181\235\139\136\235\139\164. \236\161\176\235\148\148\236\149\133 \235\130\152\236\157\180\236\184\160\235\165\188 \237\155\132\236\155\144\237\149\152\235\138\148 \236\158\172\235\160\165\234\176\128\236\157\152 \235\148\184\236\157\180\236\167\128\235\167\140 \235\143\153\236\139\156\236\151\144 \234\184\176\236\130\172\235\139\168\236\157\132 \235\143\153\234\178\189\237\149\180\236\153\148\236\151\136\234\184\176\236\151\144, \237\158\152\236\157\132 \236\150\187\234\178\140 \235\144\156 \235\146\164 \236\130\172\235\158\140\235\147\164\236\157\132 \235\143\132\236\154\176\235\169\176 \235\167\142\236\157\128 \234\179\179\236\157\132 \235\170\168\237\151\152\237\149\152\234\179\160 \236\139\182\235\139\168 \236\131\157\234\176\129\236\156\188\235\161\156 \234\184\176\236\130\172\235\139\168\236\151\144 \236\158\133\235\139\168\236\157\132 \236\158\144\236\178\152\237\150\136\236\138\181\235\139\136\235\139\164.\n\236\167\145\236\149\136\236\151\144\236\132\156 \236\154\148\236\150\145\237\149\160 \235\149\140\235\138\148 \235\175\184\236\178\152 \235\170\176\235\158\144\235\141\152 \234\183\184\235\133\128\236\157\152 \237\131\128\234\179\160\235\130\156 \237\152\184\234\184\176\236\139\172 \235\149\140\235\172\184\236\151\144 \235\139\168\236\155\144\235\147\164\236\157\128 \236\158\144\234\190\184\235\167\140 \236\150\180\235\148\148\235\161\160\234\176\128 \236\130\172\235\157\188\236\167\128\235\138\148 \237\155\132\236\155\144\236\158\144 \234\176\128\235\172\184 \236\149\132\234\176\128\236\148\168\236\157\152 \236\149\136\236\156\132\235\165\188 \235\138\152 \234\177\177\236\160\149\237\149\169\235\139\136\235\139\164. \237\149\152\236\167\128\235\167\140 \234\183\184\235\133\128\235\138\148 \235\139\168\236\155\144\235\147\164\236\157\180 \236\158\144\236\139\160\236\157\132 \235\141\148 \236\157\180\236\131\129 \236\167\128\236\188\156\236\164\152\236\149\188 \237\149\160 \235\140\128\236\131\129\236\157\180 \236\149\132\235\139\140 \237\149\156 \236\130\172\235\158\140\236\157\152 \234\176\153\236\157\128 \234\184\176\236\130\172\236\157\180\236\158\144 \235\147\177\236\157\132 \234\184\176\235\140\136 \236\136\152 \236\158\136\235\138\148 \235\143\153\235\163\140\235\161\156\236\132\156 \235\176\155\236\149\132\235\147\164\236\151\172\236\163\188\234\184\184 \235\176\148\235\158\141\235\139\136\235\139\164."
