L12_1 = "\236\160\132\234\176\136\236\158\144\235\166\172\236\157\152 \234\184\176\236\130\172, \237\148\188\236\152\164\235\132\164 \235\161\156\236\155\176\236\157\128 \236\149\132\234\181\176\236\157\152 \235\176\169\236\150\180\235\160\165\236\157\132 \234\176\149\237\153\148\236\139\156\236\188\156\236\163\188\235\138\148 \236\167\128\236\155\144\237\152\149 \236\136\152\235\185\132\236\136\152\236\158\133\235\139\136\235\139\164.\n\236\161\176\235\148\148\236\149\133\235\130\152\236\157\180\236\184\160\236\157\152 \235\182\128\235\139\168\236\158\165\236\156\188\235\161\156\236\132\156, \234\181\176\236\157\184\236\182\156\236\139\160 \236\167\145\236\149\136\236\151\144\236\132\156 \236\158\144\235\158\128 \234\183\184\235\133\128\235\138\148 \234\183\156\236\156\168\236\157\180 \236\158\136\236\150\180\236\149\188 \236\167\145\235\139\168\236\157\132 \236\152\172\235\176\148\235\165\180\234\178\140 \237\134\181\236\160\156\237\149\160 \236\136\152 \236\158\136\235\139\164\234\179\160 \236\131\157\234\176\129\237\149\169\235\139\136\235\139\164. \234\183\184\235\158\152\236\132\156 \234\183\156\236\185\153\236\160\129\236\157\184 \237\155\136\235\160\168\234\179\188 \235\139\168\236\155\144 \234\176\156\234\176\156\236\157\184\236\157\152 \236\132\177\236\139\164\236\132\177\236\157\132 \234\176\149\236\161\176\237\149\152\235\169\176, \234\176\128\235\178\188\236\154\180 \236\157\188\237\131\136\236\151\144\235\143\132 \236\149\132\236\163\188 \236\151\132\234\178\169\237\149\169\235\139\136\235\139\164. \235\139\168\236\155\144\235\147\164\236\157\128 \234\183\184\235\133\128\236\157\152 \234\183\184\235\159\176 \234\188\191\234\188\191\237\149\156 \236\132\177\235\175\184\236\151\144 \235\182\128\235\139\180\236\157\132 \235\138\144\235\129\188\235\138\148 \237\149\156\237\142\184, \236\158\144\236\139\160\235\147\164\236\157\152 \236\177\133\235\172\180\234\176\128 \234\178\176\236\189\148 \234\176\128\235\179\141\236\167\128 \236\149\138\236\157\140\236\157\132 \236\149\140\234\184\176\236\151\144 \234\183\184\235\133\128\236\157\152 \235\176\169\236\139\157 \235\152\144\237\149\156 \236\150\180\235\138\144 \236\160\149\235\143\132 \236\161\180\236\164\145\237\149\152\234\179\160 \236\158\136\236\138\181\235\139\136\235\139\164.\n\235\161\156\236\155\176 \234\176\128\235\172\184\236\151\144\236\132\160 \234\183\184\235\133\128\236\151\144\234\178\140 \235\167\142\236\157\128 \234\184\176\235\140\128\235\165\188 \234\177\184\234\179\160 \236\158\136\236\156\188\235\169\176 \234\183\184\235\133\128\234\176\128 \236\151\144\236\138\164\237\133\140\235\161\156\236\130\172\235\165\188 \235\176\128\236\150\180\235\130\180\234\179\160 \235\139\168\236\158\165\236\157\180 \235\144\152\234\184\184 \236\155\144\237\149\152\236\167\128\235\167\140, \235\139\185\236\130\172\236\158\144\235\138\148 \234\183\156\236\156\168\235\167\140\237\129\188\236\157\180\235\130\152 \235\139\168\236\158\165\236\157\132 \236\161\180\236\164\145\237\149\152\234\179\160 \236\158\136\234\184\176 \235\149\140\235\172\184\236\151\144 \234\176\156\236\157\152\236\185\152 \236\149\138\234\179\160 \235\182\128\235\139\168\236\158\165\236\157\152 \236\158\144\235\166\172\236\151\144\236\132\156 \235\179\184\235\182\132\236\157\132 \235\139\164\237\149\160 \235\191\144\236\158\133\235\139\136\235\139\164."
