5\184\144\236\151\144\236\132\156 \234\176\128\236\158\165 \236\156\160\235\167\157\237\149\156 \236\157\184\236\158\172\236\152\128\236\156\188\235\169\176 \235\167\142\236\157\128 \236\150\180\235\160\164\236\154\180 \236\158\145\236\160\132\236\157\132 \236\132\177\236\130\172\236\139\156\236\188\156 \236\153\148\235\139\164\234\179\160 \237\149\152\236\167\128\235\167\140, \235\169\180\236\160\145\236\139\164\236\151\144 \235\143\153\236\132\157\237\150\136\235\141\152 \235\143\153\235\163\140\236\157\152 \237\145\156\236\160\149\236\157\132 \235\179\180\236\149\132 \236\130\172\236\139\164\234\179\188 \234\177\176\235\166\172\234\176\128 \235\168\188 \234\178\131\236\156\188\235\161\156 \236\182\148\236\160\149\235\144\169\235\139\136\235\139\164.\n\236\139\160\234\184\176\236\136\160\236\151\144 \235\175\188\234\176\144\237\149\152\236\151\172 \236\152\168\234\176\150 \236\178\168\235\139\168 \236\160\156\237\146\136\236\157\132 \235\176\156\234\178\172\237\149\152\235\169\180 \234\176\146\236\157\128 \236\139\160\234\178\189 \236\147\176\236\167\128 \236\149\138\234\179\160 \236\134\144\236\151\144 \235\132\163\236\156\188\235\160\164 \237\149\152\234\184\176 \235\149\140\235\172\184\236\151\144, \236\181\156\234\183\188 \236\158\144\234\184\136 \235\167\136\235\160\168\236\151\144 \234\179\160\236\139\172 \236\164\145\236\157\180\235\157\188\234\179\160 \237\149\169\235\139\136\235\139\164."
