34\141\237\149\152\235\138\148 \236\185\180\236\154\180\237\132\176\236\167\128\235\167\140, \235\130\152\235\130\152\237\149\152\235\157\188\235\165\152\235\165\188 \234\183\185\237\149\156\234\185\140\236\167\128 \236\151\176\235\167\136\237\149\168\236\156\188\235\161\156\236\141\168 \234\179\160\235\147\177\234\184\137 \236\185\180\236\154\180\237\132\176\236\153\128 \235\140\128\235\147\177\237\149\156 \236\160\132\235\160\165\236\156\188\235\161\156 \236\157\184\236\160\149 \235\176\155\234\178\140 \235\144\152\236\151\136\236\138\181\235\139\136\235\139\164.\n\235\139\164\235\167\140, \234\178\128\236\136\160\236\157\152 \235\179\181\236\155\144\236\151\144 \234\179\181\236\157\132 \235\147\164\236\151\172\236\152\168 \234\176\128\235\172\184 \236\151\176\237\149\169\236\151\144\236\132\160 \234\183\184\235\133\128\234\176\128 \235\139\185\236\163\188 \234\176\156\236\157\184\236\157\132 \235\185\132\237\152\184\237\149\152\234\184\176 \236\156\132\237\149\180 \236\151\176\237\149\169\236\157\152 \234\178\128\236\136\160\236\157\132 \236\130\172\236\154\169\237\149\156\235\139\164\235\138\148 \236\130\172\236\139\164\236\151\144 \235\182\136\235\167\140\236\157\132 \234\176\150\234\179\160 \236\158\136\236\138\181\235\139\136\235\139\164."
