L14_1 = "\234\176\128\235\172\184\236\157\152 \236\150\180\235\166\176 \235\139\185\236\163\188, \235\130\152\235\130\152\237\149\152\235\157\188 \236\185\152\235\130\152\236\184\160\235\138\148 \236\185\152\236\156\160\236\157\152 \234\184\176\236\154\180\236\157\180 \234\185\131\235\147\160 \235\176\148\235\158\140\236\156\188\235\161\156 \236\149\132\234\181\176\236\157\152 \236\131\157\236\161\180\234\179\188 \236\160\129\236\157\152 \234\178\169\237\135\180\235\165\188 \235\143\153\236\139\156\236\151\144 \235\143\132\235\170\168\237\149\152\235\138\148 \236\167\128\236\155\144\234\176\128\236\158\133\235\139\136\235\139\164.\n\236\160\132\235\140\128 \235\139\185\236\163\188\234\176\128 \234\176\145\236\158\145\236\138\164\235\159\172\236\154\180 \235\179\145\237\153\152\236\156\188\235\161\156 \236\132\184\236\131\129\236\157\132 \235\150\160\235\130\172\236\157\132 \235\149\140, \236\151\176\237\149\169\236\151\144\236\132\156\235\138\148 \235\167\140\236\158\165\236\157\188\236\185\152\235\161\156 \236\185\152\235\130\152\236\184\160\235\165\188 \235\179\184\234\176\128\236\157\152 \236\131\136\235\161\156\236\154\180 \235\139\185\236\163\188\235\161\156 \236\182\148\235\140\128\237\149\152\236\152\128\236\138\181\235\139\136\235\139\164. \234\176\128\235\172\184\236\157\152 \236\139\156\236\161\176\234\176\128 \236\167\128\235\133\148\235\139\164\235\141\152 \235\176\148\235\158\140\236\157\152 \235\170\169\236\134\140\235\166\172\235\165\188 \235\147\163\235\138\148 \235\138\165\235\160\165\236\157\180 \236\185\152\235\130\152\236\184\160\236\151\144\234\178\140\235\143\132 \235\130\152\237\131\128\235\130\172\234\184\176 \235\149\140\235\172\184\236\158\133\235\139\136\235\139\164. \235\130\152\235\130\152\237\149\152\235\157\188 \234\176\128\235\172\184\236\157\128 \235\175\184\235\158\152\235\165\188 \236\149\140\235\160\164 \236\163\188\234\179\160 \236\130\172\235\158\140\236\157\152 \235\167\136\236\157\140\236\157\132 \237\151\164\236\149\132\235\1