\167\140, \236\158\133\236\130\172 \236\157\180\235\158\152 \237\149\156 \235\178\136\235\143\132 \236\158\144\235\176\156\236\160\129\236\156\188\235\161\156 \237\156\180\234\176\128\234\179\132\235\165\188 \236\147\176\236\167\128 \236\149\138\236\149\152\234\179\160, \235\167\164\236\157\188 \237\142\184\236\157\152\236\160\144\236\151\144\236\132\156 \237\152\188\236\158\144 \235\129\188\235\139\136\235\165\188 \235\149\140\236\154\176\235\138\148 \235\147\177 \236\167\128\236\182\156\236\151\144 \235\175\188\234\176\144\237\149\156 \236\132\177\237\150\165\236\157\128 \236\152\136\236\160\132\234\179\188 \235\139\164\235\166\132\236\151\134\236\150\180 \235\179\180\236\158\133\235\139\136\235\139\164.\n\234\183\184\235\159\176 \236\158\144\236\139\160\236\157\152 \235\169\180\235\170\168\235\165\188 \235\182\128\235\129\132\235\159\172\236\155\140 \237\149\152\235\138\148 \234\178\189\237\150\165\236\157\180 \236\158\136\236\156\188\235\175\128\235\161\156 \235\143\153\236\160\132\236\167\128\234\176\145\236\151\144 \235\140\128\237\149\156 \236\167\128\236\160\129\236\157\128 \236\167\128\236\150\145\237\149\180\236\163\188\236\139\156\234\184\176 \235\176\148\235\158\141\235\139\136\235\139\164."
