8\131\236\157\128 \235\182\136\234\176\128\235\138\165\237\149\180 \235\179\180\236\152\128\236\138\181\235\139\136\235\139\164. \236\132\160\236\161\176\235\147\164\236\157\128 \236\151\173\236\139\160\235\178\160\234\184\176\235\157\188 \235\182\136\235\166\172\235\138\148 \236\139\160\234\184\176\235\165\188 \236\153\132\236\132\177\237\149\160 \236\136\152\235\167\140 \236\158\136\235\139\164\235\169\180, \234\183\184\234\178\131\236\157\180 \237\149\180\235\139\181\236\157\180 \235\144\152\235\166\172\235\157\188 \235\175\191\236\151\136\236\138\181\235\139\136\235\139\164. \n\236\139\156\235\160\168 \235\129\157\236\151\144 \236\139\160\236\157\152 \234\178\128\236\157\132 \236\134\144\236\151\144 \236\165\148 \234\183\184\235\133\128\235\138\148 \236\162\133\235\167\144\236\157\180\235\157\188\235\138\148 \236\154\180\235\170\133\236\157\132 \235\178\160\234\179\160 \235\130\152\236\149\132\234\176\145\235\139\136\235\139\164."
