L39_1 = "\235\132\164\237\151\164\235\170\168\237\138\184 \235\160\136\236\157\180\235\138\148 \236\158\144\236\139\160\234\179\188 \237\155\132\236\151\180 \236\149\132\234\181\176\236\157\180 \235\176\155\235\138\148 \234\179\181\234\178\169\236\157\132 \235\176\152\234\178\169\237\149\152\236\151\172 \236\149\132\234\181\176 \235\179\180\237\152\184\236\151\144 \237\138\185\237\153\148\235\144\156 \235\148\148\237\142\156\235\141\148\236\158\133\235\139\136\235\139\164.\n\235\168\184\235\130\152\235\168\188 \234\179\188\234\177\176, \236\160\156\234\181\173\236\157\152 \237\143\137\235\175\188 \236\182\156\236\139\160\236\157\180\236\151\136\235\141\152 \237\149\156 \236\134\140\235\133\132\236\157\128 \236\154\176\236\151\176\237\149\156 \234\179\132\234\184\176\235\161\156 \234\181\172\236\155\144\236\158\144\234\176\128 \235\144\152\236\150\180 \234\184\176\236\130\172\235\139\168\234\179\188 \237\149\168\234\187\152 \236\132\184\236\131\129\236\157\132 \234\181\172\236\155\144\237\149\152\234\184\176 \236\156\132\237\149\156 \236\151\172\236\160\149\236\157\132 \235\150\160\235\130\172\236\138\181\235\139\136\235\139\164. \236\160\156\234\181\173\236\157\152 \236\139\160\235\175\188\235\147\164\236\157\128 \234\183\184\236\153\128 \234\184\176\236\130\172\235\139\168\236\157\180 \236\132\184\236\131\129\236\157\132 \234\181\172\237\149\160 \234\178\131\236\157\132 \236\157\152\236\139\172\236\185\152 \236\149\138\236\149\152\234\179\160, \236\134\140\235\133\132 \235\152\144\237\149\156 \234\181\172\236\155\144\236\157\132 \236\158\144\236\139\160\236\157\152 \236\177\133\235\172\180\235\161\156 \236\130\188\236\149\152\236\138\181\235\139\136\235\139\164.\n\236\152\164\235\158\156 \236\139\156\234\176\132\236\157\180 \236\167\128\235\130\156 \237\155\132, \234\178\176\234\181\173 \236\160\156\234\181\173\236\157\128 \235\169\184\235\167\157\237\149\152\236\152\128\234\179\160 \234\183\184\234\176\128 \234\181\172\237\149\160 \236\139\160\235\175\188\236\161\176\236\176\168 \235\141\148\235\138\148 \235\130\168\236\167\128 \236\149\138\234\178\140 \235\144\152\236\151\136\236\167\128\235\167\140, \236\134\140\235\133\132\236\157\128 \236\132\184\236\131\129\236\157\132 \234\181\172\237\149\152\235\160\164\235\138\148 \236\151\172\236\160\149\236\157\132 \237\143\172\234\184\176\237\149\160 \236\136\152 \236\151\134\236\151\136\236\138\181\235\139\136\235\139\164. \236\158\144\236\139\160\236\151\144\234\178\140 \234\181\172\236\155\144\236\157\132 \235\176\148\235\158\144\235\141\152 \236\157\180\235\147\164\236\157\152 \234\184\176\235\140\128\235\165\188 \234\178\176\236\189\148 \237\151\155\235\144\152\236\157\180 \237\149\160 \236\136\152 \236\151\134\236\151\136\234\184\176\236\151\144.\n\234\183\184\235\166\172\234\179\160 \235\152\144\235\139\164\236\139\156 \236\152\164\235\158\156 \236\139\156\234\176\132\236\157\180 \236\167\128\235\130\156 \236\167\128\234\184\136, \237\149\156\235\149\140 \234\181\172\236\155\144\236\158\144\235\157\188 \236\185\173\236\134\161\235\176\155\235\141\152 \236\131\129\235\131\165\237\149\156 \236\134\140\235\133\132\236\157\128 \235\167\136\236\185\168\235\130\180 \234\185\168\235\139\171\234\179\160 \235\167\144\236\149\152\236\138\181\235\139\136\235\139\164. \234\181\172\236\155\144\236\157\132 \237\150\165\237\149\156 \236\151\172\236\160\149\236\157\152 \235\129\157\236\157\128 \236\138\164\236\138\164\235\161\156 \236\185\168\235\158\181\236\158\144\234\176\128 \235\144\152\236\150\180 \235\139\164\235\165\184 \236\132\184\234\179\132\235\165\188 \235\169\184\235\167\157\236\139\156\236\188\156\235\178\132\235\166\172\235\138\148 \234\178\131\235\191\144\236\157\180\235\157\188\235\138\148 \234\178\131\236\157\132."
