L40_1 = "\236\178\152\236\157\140\236\151\144\235\138\148 \237\149\156 \236\130\172\235\158\140\236\157\132 \235\167\140\235\130\152\234\184\176 \236\156\132\237\149\180\236\132\156 \236\139\156\236\158\145\237\149\156 \235\176\169\236\134\161\236\157\188 \235\191\144\236\157\180\236\151\136\236\157\132\236\167\128\235\143\132 \235\170\168\235\166\133\235\139\136\235\139\164. \237\149\152\236\167\128\235\167\140 \237\149\152\237\138\184\235\178\160\235\166\172\236\151\144\236\132\156\236\157\152 \235\176\169\236\134\161 \237\153\156\235\143\153\236\157\132 \237\134\181\237\149\180 \234\176\128\236\157\128\236\157\128 \236\160\144\236\160\144 \235\166\172\235\141\148\235\161\156\236\132\156\236\157\152 \236\158\172\235\138\165\236\157\132 \235\147\156\235\159\172\235\130\180\234\184\176 \236\139\156\236\158\145\237\150\136\236\138\181\235\139\136\235\139\164.\n\235\163\168\235\175\184\236\157\152 \235\132\152\236\185\152\235\138\148 \236\158\144\236\139\160\234\176\144\234\179\188 \235\179\180\235\175\184\236\157\152 \235\138\144\234\184\139\237\149\156 \236\151\172\236\156\160\235\161\156\236\155\128, \234\183\184\235\166\172\234\179\160 \235\175\184\236\149\188\236\157\152 \236\152\164\235\158\156 \235\176\169\236\134\161 \234\178\189\237\151\152\226\128\166. \234\176\129\236\158\144 \234\176\156\236\132\177 \234\176\149\237\149\156 \235\167\180\235\178\132\235\147\164 \236\130\172\236\157\180\236\151\144\236\132\156 \234\183\184\235\147\164\236\157\152 \235\167\164\235\160\165\236\157\132 \236\149\132\236\154\176\235\165\188 \236\136\152 \236\158\136\235\138\148 \236\185\180\235\166\172\236\138\164\235\167\136\235\165\188 \236\150\187\234\178\140 \235\144\156 \234\178\131\236\157\180\236\163\160.\n\235\176\169\236\134\161\236\151\144\236\132\156\235\143\132, \234\183\184\235\166\172\234\179\160 \235\172\180\235\140\128 \236\156\132\236\151\144\236\132\156\235\143\132 \234\176\128\236\157\128\236\157\152 \235\166\172\235\147\156\235\138\148 \236\158\144\236\139\160\236\157\180 \236\149\158\236\151\144 \236\132\156\236\167\128 \236\149\138\235\141\148\235\157\188\235\143\132, \235\167\180\235\178\132\235\147\164 \234\176\129\236\158\144\236\157\152 \235\138\165\235\160\165\236\157\132 \236\181\156\235\140\128\237\149\156 \235\129\140\236\150\180\235\131\133\235\139\136\235\139\164.\n\235\141\149\235\182\132\236\151\144 \236\181\156\234\183\188 \237\149\152\237\138\184\235\178\160\235\166\172\235\138\148 \235\169\148\236\157\180\236\160\128\236\151\144\236\132\156 \236\163\188\235\170\169\237\149\160\235\167\140\237\149\156 \236\149\132\236\157\180\235\143\140 \234\183\184\235\163\185\236\156\188\235\161\156 \236\138\164\237\133\157 \236\151\133 \237\150\136\235\139\164\235\138\148 \237\143\137\234\176\128\235\165\188 \235\176\155\234\179\160 \236\158\136\236\163\160.\n\236\149\132\236\167\129 \235\139\164\235\165\184 \235\167\180\235\178\132\235\147\164\236\151\144 \235\185\132\237\149\180 \236\182\164\234\179\188 \235\133\184\235\158\152\235\138\148 \236\132\156\237\136\176 \237\142\184\236\157\180\236\167\128\235\167\140, \236\157\180\236\160\156 \234\176\128\236\157\128\236\157\128 \236\138\164\237\143\172\237\138\184\235\157\188\236\157\180\237\138\184\235\165\188 \235\176\155\236\156\188\235\169\176 \236\152\164\235\138\152\235\143\132 \237\140\172\235\147\164\236\157\132 \237\150\165\237\149\180 \237\153\152\237\149\156 \235\175\184\236\134\140 \236\167\128\236\157\132 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.\n\236\150\184\236\160\156, \236\150\180\235\148\148\236\132\156\235\147\160 \236\158\144\236\139\160\236\157\152 \234\176\128\236\158\165 \237\129\176 \237\140\172\236\157\184 \236\132\160\236\131\157\235\139\152\236\157\180 \236\167\128\236\188\156\235\180\144 \236\163\188\236\139\160\235\139\164\235\138\148 \234\177\184 \236\149\140\234\179\160 \236\158\136\236\156\188\235\139\136\234\185\140\236\154\148."
