L28_1 = "\236\136\152\235\166\172\236\149\188\236\151\144 \235\140\128\237\149\156 \234\184\176\235\161\157\236\157\128 \236\157\184\234\176\132\236\157\152 \234\184\176\236\150\181\236\157\132 \237\143\172\237\149\168\237\149\156 \234\183\184 \236\150\180\235\150\164 \235\141\176\236\157\180\237\132\176\235\178\160\236\157\180\236\138\164\236\151\144\235\143\132 \235\130\168\236\149\132\236\158\136\236\167\128 \236\149\138\236\138\181\235\139\136\235\139\164. \235\148\176\235\157\188\236\132\156 \234\183\184\235\133\128\234\176\128 \236\134\140\236\167\128\237\149\152\234\179\160 \236\158\136\235\138\148 \234\179\160\236\156\160 \235\172\180\236\158\165\236\157\132 \237\134\181\237\149\180 \236\160\149\236\178\180\235\165\188 \236\156\160\236\182\148\237\149\180 \235\179\184 \235\176\148, \237\149\156\235\149\140 \237\152\132\236\139\164\235\161\156 \235\182\128\236\131\129\237\149\156 \237\138\185\236\157\180 \236\185\168\236\139\157\236\178\180\235\147\164\236\157\132 \236\132\172\235\169\184\237\149\152\235\138\148 \236\158\132\235\172\180\235\165\188 \235\167\161\236\149\152\235\141\152 \234\178\131\236\156\188\235\161\156 \236\182\148\236\184\161\235\144\169\235\139\136\235\139\164.\n\236\181\156\234\183\188 \236\136\152\235\166\172\236\149\188\235\138\148 \234\180\128\234\180\145 \237\154\140\236\130\172, \235\176\148\235\163\168\235\130\152 \237\136\172\236\150\180\236\151\144\236\132\156 \234\176\128\236\157\180\235\147\156 \236\157\188\236\157\132 \237\149\152\235\138\148 \234\178\131\236\156\188\235\161\156 \237\153\149\236\157\184\235\144\152\236\151\136\236\138\181\235\139\136\235\139\164.\234\176\128\236\157\180\235\147\156\236\185\152\234\179\160\235\138\148 \236\167\128\235\166\172\235\130\152 \236\151\173\236\130\172\236\151\144 \235\140\128\237\149\156 \236\167\128\236\139\157\236\157\180 \236\160\132\235\172\180\237\149\152\234\179\160, \236\134\144\235\139\152\236\151\144\234\178\140 \235\182\136\236\185\156\236\160\136\237\149\152\234\184\176 \236\157\188\236\145\164\235\157\188 \236\181\156\236\149\133\236\157\152 \234\176\128\236\157\180\235\147\156 \237\155\132\235\179\180\236\151\144 \236\157\180\235\166\132\236\157\132 \236\152\172\235\166\172\235\138\148 \237\149\156\237\142\184, \236\136\152\235\166\172\236\149\188 \235\141\149\235\182\132\236\151\144 \236\185\168\236\139\157\236\178\180\236\157\152 \236\138\181\234\178\169\236\156\188\235\161\156\235\182\128\237\132\176 \235\170\169\236\136\168\236\157\132 \234\181\172\237\149\156 \234\180\128\234\180\145\234\176\157\235\147\164\236\157\152 \237\152\184\237\143\137 \236\157\188\236\131\137\236\157\184 \235\166\172\235\183\176 \235\141\149\235\182\132\236\151\144 \237\143\137\236\160\144\236\157\128 \236\160\156\235\178\149 \235\134\146\236\157\128 \237\142\184\236\158\133\235\139\136\235\139\164.\n\236\167\128\234\184\136\236\157\128 \234\183\184\236\160\128 \236\130\172\236\167\132\236\157\132 \236\176\141\234\184\176 \236\156\132\237\149\180 \234\176\128\236\157\180\235\147\156\235\165\188 \237\149\156 \234\178\131\236\178\152\235\159\188 \235\179\180\236\157\180\236\167\128\235\167\140, \234\183\184\235\133\128\236\157\152 \236\160\149\237\153\149\237\149\156 \235\170\169\236\160\129\236\157\180 \235\172\180\236\151\135\236\157\184\236\167\128 \236\149\140\235\160\164\236\167\132 \235\176\148\235\138\148 \236\151\134\236\138\181\235\139\136\235\139\164."
