41\235\138\148 \235\173\135 \236\150\180\235\166\176\236\157\180\235\147\164\234\179\188 \236\134\140\236\136\152\236\157\152 \236\132\177\236\157\184 \235\130\168\236\132\177\236\157\132 \235\182\136\235\159\172 \235\170\168\236\156\188\235\138\148 \236\157\180\236\156\160\236\157\180\236\158\144, \236\157\180\235\178\136 \235\139\172 \236\181\156\234\179\160\236\157\152 \234\176\128\236\157\180\235\147\156 \236\131\129\236\157\132 \235\176\155\236\157\128 \235\185\132\234\178\176\236\158\133\235\139\136\235\139\164.\n\234\176\132\237\152\185, \237\152\188\236\158\163\235\167\144\236\157\132 \237\157\165\236\150\188\234\177\176\235\166\176\235\139\164\234\177\176\235\130\152, \235\172\188\234\177\180\236\151\144 \236\157\180\235\166\132\236\157\132 \235\182\153\236\157\180\234\179\160 \235\140\128\237\153\148\235\165\188 \237\149\152\235\138\148 \234\178\189\236\154\176\234\176\128 \236\158\136\236\167\128\235\167\140, \237\152\188\236\158\144 \236\167\128\235\131\136\235\141\152 \236\139\156\234\176\132\236\157\180 \234\184\184\236\151\136\235\141\152 \236\152\129\237\150\165\236\157\180\235\139\136 \236\157\180 \235\170\168\236\138\181\236\157\132 \235\170\169\234\178\169\237\149\156\235\139\164\235\169\180 \235\170\168\235\165\184 \236\178\153\237\149\180\236\163\188\236\139\156\234\184\176\235\165\188 \235\176\148\235\158\141\235\139\136\235\139\164."
