L30_1 = "\237\140\140\237\139\176\235\167\136\235\138\148 \236\158\144\236\139\160\235\167\140\236\157\152 \236\160\149\236\157\152\235\165\188 \235\148\176\235\165\180\235\169\176 \236\139\160\236\157\152\235\165\188 \235\172\180\234\184\176\235\161\156 \236\130\188\236\138\181\235\139\136\235\139\164. \235\161\156\237\132\176\236\138\164\236\157\152 \235\178\148\236\163\132 \236\139\160\235\148\148\236\188\128\236\157\180\237\138\184\235\147\164\236\157\132 \237\143\137\236\160\149\237\149\156 \234\183\184\235\133\128\234\176\128 \236\138\164\236\138\164\235\161\156 \234\180\128\235\166\172\234\181\173 \236\149\132\235\158\152\236\151\144 \235\147\164\236\150\180\234\176\132 \234\178\131 \235\152\144\237\149\156 \236\156\160\235\170\133\235\172\180\236\139\164\237\149\180\236\167\132 \235\178\149\236\157\132 \235\132\152\236\150\180 \235\182\136\236\157\152\235\165\188 \236\139\172\237\140\144\237\149\160 \236\136\152 \236\158\136\235\138\148 \237\158\152\236\157\132 \236\155\144\237\150\136\234\184\176 \235\149\140\235\172\184\236\157\180\236\163\160. \n\237\149\152\236\167\128\235\167\140 \234\183\184\235\133\128\235\138\148 \234\178\176\236\189\148 \234\180\128\235\166\172\234\181\173\236\157\152 \234\182\140\237\149\156\236\157\132 \235\130\168\236\154\169\237\149\152\236\167\128 \236\149\138\236\138\181\235\139\136\235\139\164. \234\180\128\235\166\172\234\181\173\236\157\152 \236\136\152\236\158\165\235\147\164\235\167\140\236\157\180 \236\152\172\235\176\148\235\165\184 \237\140\144\235\139\168\236\157\132 \237\149\160 \236\136\152 \236\158\136\235\139\164\234\179\160 \235\175\191\236\156\188\235\169\176, \234\183\184\235\147\164\236\157\152 \236\167\128\236\139\156\236\151\144 \235\148\176\235\165\188 \235\191\144\236\157\180\236\163\160. \n\235\172\188\235\161\160 \234\183\184\235\133\128\235\143\132 \234\180\128\235\166\172\234\181\173\236\157\152 \236\132\160\237\131\157\236\157\180 \235\172\180\236\161\176\234\177\180 \236\152\179\235\139\164\234\179\160 \236\131\157\234\176\129\237\149\152\236\167\132 \236\149\138\236\156\188\235\169\176, \234\178\189\237\151\152\236\157\180 \235\182\128\236\161\177\237\149\156 \236\131\129\234\180\128\236\151\144\234\178\144 \236\161\176\236\150\184\236\157\132 \236\149\132\235\129\188\236\167\128 \236\149\138\235\138\148 \235\170\168\236\138\181\236\157\132 \235\179\180\236\158\133\235\139\136\235\139\164. \n\236\130\172\235\158\140\235\147\164\236\157\128 \237\140\140\237\139\176\235\167\136\236\157\152 \236\130\172\235\130\152\236\154\180 \236\157\184\236\131\129 \235\149\140\235\172\184\236\151\144 \236\132\160\236\158\133\234\178\172\236\157\132 \234\176\150\234\179\164 \237\149\152\236\167\128\235\167\140, \236\130\172\236\139\164 \234\183\184\235\133\128\235\138\148 \235\167\164\236\130\172\236\151\144 \236\185\168\236\176\169\237\149\152\234\179\160 \236\167\132\236\164\145\237\149\152\235\169\176 \236\150\180\235\166\176\236\149\132\236\157\180\236\151\144\234\178\144 \237\149\156\236\151\134\236\157\180 \236\152\168\236\160\149 \236\150\180\235\166\176 \237\131\156\235\143\132\235\165\188 \235\179\180\236\158\133\235\139\136\235\139\164."
