L31_1 = "\237\142\160\235\166\173\236\138\164\235\138\148 \235\140\128\236\160\149\237\153\148\236\160\132\236\159\129 \235\139\185\236\139\156 \236\185\168\236\139\157\236\156\188\235\161\156 \235\182\132\236\151\180\235\144\156 \234\181\173\234\176\128\235\165\188 \235\182\129\235\176\169\237\149\169\236\157\152\236\178\180\235\157\188\235\138\148 \236\157\180\235\166\132\236\156\188\235\161\156 \235\139\164\236\139\156 \237\134\181\237\149\169\237\149\156 \236\152\129\236\155\133\236\160\129\236\157\184 \236\157\184\235\172\188\236\158\133\235\139\136\235\139\164. \235\185\132\235\161\157 \234\183\184 \236\152\129\236\155\133\236\157\128 \237\151\140\236\139\160 \235\129\157\236\151\144 \236\138\164\235\159\172\236\161\140\236\167\128\235\167\140, \234\183\184\236\157\152 \235\148\184\236\157\180 \236\149\132\235\178\132\236\167\128\236\157\152 \236\157\152\236\167\128\236\153\128 \236\157\180\235\166\132\236\157\132 \235\172\188\235\160\164\235\176\155\236\149\132 \237\149\169\236\157\152\236\178\180\235\165\188 \236\157\180\235\129\132\235\138\148 \236\164\145\236\158\133\235\139\136\235\139\164. \n\234\183\184\235\133\128\235\138\148 \235\140\128 \236\185\168\236\139\157\236\160\132\236\151\144 \237\138\185\237\153\148\235\144\156 \234\181\176\235\140\128\235\165\188 \236\150\145\236\132\177\237\149\152\236\151\172 \234\183\184\235\166\188\236\158\144\235\165\188 \237\134\160\235\178\140\237\149\152\234\179\160, \236\185\168\236\139\157\236\156\188\235\161\156 \235\178\132\235\160\164\236\167\132 \235\149\133\236\157\132 \236\160\149\237\153\148\237\149\180 \236\158\131\236\150\180\235\178\132\235\166\176 \237\146\141\236\154\148\235\165\188 \235\144\152\236\176\190\236\156\188\235\169\176 \235\167\142\236\157\128 \234\181\173\235\175\188\235\147\164\235\161\156\235\182\128\237\132\176 \236\161\180\234\178\189\236\157\132 \236\150\187\234\179\160 \236\158\136\236\138\181\235\139\136\235\139\164. \234\183\184 \236\132\177\234\179\188\236\157\152 \236\157\180\235\169\180\236\151\144\235\138\148 \236\157\184\235\165\156\236\157\132 \234\177\176\236\138\164\235\165\180\235\138\148 \235\172\180\236\136\152\237\149\156 \236\139\164\237\151\152\234\179\188 \237\157\172\236\131\157\236\157\180 \236\158\136\236\151\136\236\167\128\235\167\140 \234\183\184 \236\167\132\236\139\164\236\157\132 \236\149\132\235\138\148 \236\157\180\235\138\148 \234\183\185\237\158\136 \236\157\188\235\182\128\236\158\133\235\139\136\235\139\164. \n\237\142\160\235\166\173\236\138\164\236\157\152 \234\181\176\235\140\128\235\138\148 \235\182\136\236\130\172 \236\139\164\237\151\152\236\156\188\235\161\156 \235\167\140\235\147\164\236\150\180\236\167\132 \237\149\169\236\132\177 \236\157\184\234\176\132\236\157\180\235\169\176, \234\183\184\235\147\164\236\157\180 \236\154\180\236\154\169\237\149\152\235\138\148 \236\139\160\236\152\136 \235\179\145\234\184\176 \236\178\180\235\165\180\235\133\184\235\179\180\234\183\184\235\138\148 \234\184\176\234\179\132\234\176\128 \236\149\132\235\139\140 \234\183\184\235\166\188\236\158\144\235\157\188\235\138\148 \236\157\180\236\149\188\234\184\176\234\176\128 \236\158\136\236\167\128\235\167\140, \236\157\180\235\138\148 \236\157\140\235\170\168\235\161\160\236\156\188\235\161\156 \236\183\168\234\184\137\235\144\160 \235\191\144\236\158\133\235\139\136\235\139\164. \237\140\140\237\142\184\237\153\148\235\144\156 \236\166\157\236\150\184\234\179\188 \236\134\140\235\172\184\236\157\180 \236\158\136\236\157\132 \235\191\144, \234\176\144\237\158\136 \234\183\184 \236\167\132\236\139\164\236\157\132 \236\166\157\235\170\133\237\149\160 \236\136\152 \236\158\136\235\138\148 \236\130\172\235\158\140\236\157\128 \236\150\180\235\148\148\236\151\144\235\143\132 \236\151\134\236\156\188\235\139\136\234\185\140\236\154\148."
