35\141\156\235\160\129\234\177\176\235\166\172\235\138\148 \235\169\180\235\170\168\235\165\188 \236\167\128\235\139\136\234\179\160 \236\158\136\236\138\181\235\139\136\235\139\164. \235\140\128\237\145\156\236\160\129\236\156\188\235\161\156 \234\183\184\235\133\128\234\176\128 \236\167\128\235\139\140 \236\151\176\236\149\160\234\180\128\236\157\128 \235\143\153\236\161\177\236\157\184 \236\151\152\237\148\132\235\147\164\236\161\176\236\176\168 \234\179\160\234\176\156\235\165\188 \236\160\128\236\157\132 \236\160\149\235\143\132\235\161\156 \236\136\156\234\178\176\237\149\169\235\139\136\235\139\164.\n\236\132\160\236\178\156\236\160\129 \235\167\136\235\178\149 \236\130\172\236\154\169 \236\162\133\236\161\177\236\157\184 \236\151\152\237\148\132\235\139\181\234\178\140 \235\155\176\236\150\180\235\130\156 \235\167\136\235\178\149\235\138\165\235\160\165\236\157\132 \236\167\128\235\133\148\236\157\132 \235\191\144\235\167\140 \236\149\132\235\139\136\235\157\188 \236\185\152\236\156\160\235\138\165\235\160\165\234\179\188 \234\183\188\236\160\145 \236\160\132\237\136\172\235\138\165\235\160\165\234\185\140\236\167\128 \234\176\128\235\175\184\237\149\156 \235\134\146\236\157\128 \236\156\160\237\139\184\235\166\172\237\139\176\235\165\188 \235\176\156\237\156\152\237\149\169\235\139\136\235\139\164. \234\178\189\237\151\152\234\179\188 \234\184\176\234\181\144 \236\151\173\236\139\156 \235\155\176\236\150\180\235\130\156 \235\178\160\237\133\140\235\158\145\236\157\180\234\184\176\236\151\144, \236\156\132\237\151\152\237\149\156 \235\139\168\235\143\133 \236\158\132\235\172\180\235\143\132 \234\177\176\235\166\172\235\130\140 \236\151\134\236\157\180 \236\136\152\237\150\137\237\149\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164."
