131\129 \236\157\180\237\155\132, \236\158\172\237\153\156\236\157\152 \236\157\188\237\153\152\236\156\188\235\161\156 \234\176\128\235\178\188\236\154\180 \235\172\180\234\184\176\235\165\188 \236\147\176\235\138\148 \236\164\145\236\157\180\235\157\188 \236\163\188\236\158\165\237\149\152\236\167\128\235\167\140 CRF\236\182\156\235\160\165\234\179\188 \234\176\156\236\157\184 \234\184\176\235\159\137\236\151\144\235\138\148 \235\179\132\235\139\164\235\165\184 \236\157\180\236\131\129\236\157\180 \236\151\134\235\138\148 \234\178\131\236\156\188\235\161\156 \237\153\149\236\157\184\235\144\144\236\138\181\235\139\136\235\139\164."
