L40_1 = "\235\140\128\236\131\129 \234\180\128\236\176\176 \234\178\176\234\179\188. \236\157\188\235\176\152\236\160\129\236\157\184 \236\185\168\236\139\157\236\178\180\236\153\128 \235\139\172\235\166\172 \236\185\180\236\154\180\237\132\176\236\157\152 CRF\236\151\144 \235\176\152\236\157\145\237\149\152\235\138\148 \236\157\180\235\160\136\234\183\164\235\159\172\235\161\156 \237\140\144\235\170\133. \235\139\164\236\136\152\236\157\152 \235\176\148\236\157\180\235\159\172\236\138\164\234\176\128 \235\170\168\236\151\172 \235\167\140\235\147\164\236\150\180\236\167\132 \237\149\152\236\157\180\235\184\140\235\167\136\236\157\184\235\147\156\237\152\149 \236\185\168\236\139\157\236\178\180. \n\237\153\156\235\143\153 \236\139\156\236\151\148 \236\157\184\234\176\132 \237\152\149\237\131\156\235\165\188 \236\183\168\237\149\152\236\167\128\235\167\140, \236\185\168\236\139\157 \236\151\144\235\132\136\236\167\128\235\165\188 \235\179\180\234\180\128\237\149\152\235\138\148 \234\184\176\234\180\128(\235\191\148\234\179\188 \234\188\172\235\166\172\235\161\156 \236\182\148\236\160\149)\236\157\132 \236\136\168\234\184\176\236\167\128 \235\170\187\237\149\180 \236\157\152\235\165\152\235\165\188 \237\153\156\236\154\169\237\149\152\235\138\148 \234\178\131\236\156\188\235\161\156 \235\179\180\236\158\132. \n\236\157\184\234\176\132\236\157\152 \237\150\137\235\143\153\236\157\132 \234\180\128\236\176\176\237\149\152\235\138\148 \235\141\176 \234\180\128\236\139\172\236\157\132 \235\179\180\236\157\180\235\169\176, \234\183\184 \236\155\144\235\166\172\235\165\188 \236\157\180\237\149\180\237\149\152\235\160\164\234\179\160 \237\149\152\235\138\148 \235\147\177 \235\134\146\236\157\128 \236\167\128\235\138\165\236\157\132 \234\176\128\236\167\132 \234\178\131\236\156\188\235\161\156 \236\182\148\236\160\149. \237\138\185\237\158\136 \235\178\148\236\163\132\236\153\128 \236\132\160\236\149\133\236\157\180\235\158\128 \234\176\156\235\133\144\236\151\144 \235\140\128\237\149\180 \234\185\138\236\157\128 \237\157\165\235\175\184\235\165\188 \234\176\150\234\179\160 \236\158\136\236\157\140. \237\149\152\236\167\128\235\167\140 CRF\235\165\188 \237\157\161\236\136\152\237\149\152\234\179\160 \236\139\182\236\150\180\237\149\152\235\138\148 \235\179\184\235\138\165 \236\149\158\236\151\144\236\132\160 \235\148\177\237\158\136 \235\140\128\236\131\129\236\157\152 \236\132\160\237\149\168\234\179\188 \236\149\133\237\149\168\236\157\132 \234\179\160\235\160\164\237\149\152\236\167\128 \236\149\138\235\138\148 \235\147\175\237\149\168. \n\236\139\156\234\176\132\234\179\188 \236\152\136\236\130\176\236\157\180 \236\158\136\235\139\164\235\169\180 \236\157\184\234\176\132\234\179\188\236\157\152 \234\179\181\236\131\157 \234\176\128\235\138\165 \236\151\172\235\182\128\236\151\144 \235\140\128\237\149\156 \236\139\164\237\151\152\236\157\132 \236\182\148\236\167\132\237\149\160 \236\152\136\236\160\149. \n\236\156\132 \235\130\180\236\154\169\236\157\128 \235\161\160 \235\166\172 \235\176\149\236\130\172\236\157\152 \236\151\176\234\181\172 \235\179\180\234\179\160\236\132\156\236\151\144\236\132\156 \235\176\156\236\183\140\235\144\168."
