6\151\136\236\163\160.\n\235\163\168\236\139\156\236\149\132 \235\166\191\236\167\128\234\176\128 \235\143\136\236\157\132 \235\178\140\236\150\180\236\149\188 \237\149\152\235\138\148 \236\157\180\236\156\160\235\138\148 \234\176\132\235\139\168\237\149\169\235\139\136\235\139\164. \235\176\148\235\161\156 \235\179\145\236\157\132 \236\185\152\235\163\140\237\149\152\234\184\176 \236\156\132\237\149\180\236\132\156\236\158\133\235\139\136\235\139\164. \234\183\184\235\133\128\234\176\128 \234\177\184\235\166\176 \235\179\145\236\151\144 \235\140\128\237\149\180\236\132\156 \236\149\140\235\160\164\236\167\132 \235\176\148\234\176\128 \236\151\134\236\167\128\235\167\140, \235\179\180\235\166\132\235\139\172\236\157\180 \235\156\168\235\138\148 \235\130\160\235\167\140 \235\144\152\235\169\180 \235\170\168\236\138\181\236\157\132 \234\176\144\236\182\152\235\139\164\235\138\148 \236\160\144, \235\176\156\235\160\140\237\139\176\235\136\132\236\138\164 \236\136\152\235\143\132\236\155\144\236\157\132 \234\183\188\234\177\176\236\167\128\235\161\156 \235\145\148\235\139\164\235\138\148 \236\160\144\236\151\144\236\132\156 \237\143\137\235\178\148\237\149\156 \235\179\145\236\157\180 \236\149\132\235\139\136\235\157\188\235\138\148 \236\182\148\236\184\161\235\167\140 \237\149\160 \235\191\144\236\158\133\235\139\136\235\139\164."
