L43_1 = "\236\185\180\237\131\128\235\166\172\235\130\152\235\138\148 \237\149\156\235\149\140, \234\184\176\235\143\132\235\161\156 \235\170\168\235\147\160 \234\178\131\236\157\132 \236\157\180\235\164\132\235\130\188 \236\136\152 \236\158\136\235\139\164\234\179\160 \236\131\157\234\176\129\237\150\136\236\138\181\235\139\136\235\139\164. \237\131\128\236\152\164\235\165\180\235\138\148 \234\176\136\236\166\157\236\157\132 \237\143\172\235\143\132 \236\163\188\236\138\164\235\161\156 \236\139\157\237\158\136\234\179\160, \234\179\160\237\149\180\236\132\177\236\130\172\235\161\156 \236\158\144\236\139\160\236\157\152 \236\163\132\235\165\188 \235\185\140\235\169\176 \236\160\128\236\163\188\234\176\128 \236\130\172\235\157\188\236\167\128\234\184\184 \235\176\148\235\158\144\236\163\160. \237\149\152\236\167\128\235\167\140 \234\179\167 \236\158\144\236\139\160\236\157\152 \235\176\148\235\158\140\236\157\128 \234\184\176\235\143\132\235\167\140\236\156\188\235\161\156\235\138\148 \236\157\180\235\164\132\236\167\136 \236\136\152 \236\151\134\235\139\164\235\138\148 \236\130\172\236\139\164\236\157\132 \234\185\168\235\139\172\236\149\152\236\138\181\235\139\136\235\139\164.\n\236\185\180\237\131\128\235\166\172\235\130\152\235\138\148 \236\150\180\235\166\180 \236\160\129, \236\160\128\236\163\188\235\165\188 \237\146\128\234\184\176 \236\156\132\237\149\180 \234\179\160\237\150\165\236\157\132 \235\150\160\235\130\156 \234\178\131\236\178\152\235\159\188 \235\152\144\235\139\164\236\139\156 \236\160\128\236\163\188\235\165\188 \237\146\128\234\184\176 \236\156\132\237\149\180 \236\132\177\237\153\169\236\178\173\236\157\132 \235\150\160\235\130\172\236\138\181\235\139\136\235\139\164. \235\185\132\235\161\157 \236\185\180\237\131\128\235\166\172\235\130\152\236\153\128 \237\149\168\234\187\152\237\149\152\235\138\148 \236\157\180\235\147\164\236\157\128 \236\150\180\235\148\152\234\176\128 \236\136\152\236\131\129\237\149\152\234\179\160 \236\136\168\234\184\176\235\138\148 \234\178\131\235\143\132 \235\167\142\236\157\128 \236\157\180\235\139\168\236\157\180\236\167\128\235\167\140, \234\183\184\235\133\128\236\157\152 \236\178\152\236\167\128\235\165\188 \235\136\132\234\181\172\235\179\180\235\139\164 \236\158\152 \236\157\180\237\149\180\237\149\152\234\179\160 \236\158\136\236\163\160. \236\160\128\236\163\188\235\161\156 \236\157\184\237\149\156 \237\148\188\236\157\152 \234\176\136\236\166\157\236\157\132 \236\158\160\236\158\172\236\154\176\235\138\148 \234\178\131\236\157\128 \235\172\180\236\178\153\236\157\180\235\130\152 \236\150\180\235\160\181\236\167\128\235\167\140, \234\183\184\235\133\128\236\153\128 \235\156\187\236\157\132 \234\176\153\236\157\180\237\149\152\235\138\148 \236\157\180\235\147\164\236\157\180 \237\149\168\234\187\152\235\157\188\235\169\180 \236\185\180\237\131\128\235\166\172\235\130\152\235\138\148 \236\150\180\235\150\187\234\178\140\235\147\160 \234\178\172\235\142\140\235\130\188 \236\136\152 \236\158\136\236\157\132 \234\178\129\235\139\136\235\139\164."
