L6_1 = "\234\177\176\237\149\180\234\182\129, \234\178\140\236\158\144\235\166\172\236\157\152 \234\184\176\236\130\172 \236\149\132\236\133\128\235\157\188 \237\148\132\235\161\156\236\178\180\235\139\136\236\185\180\235\138\148 \235\185\132\234\181\144\236\160\129 \236\181\156\234\183\188\236\151\144 \236\131\157\236\161\180\236\157\180 \237\153\149\236\157\184\235\144\156 \235\160\136\235\147\156 \236\139\156\237\148\132\237\138\184\236\157\152 \236\157\188\236\155\144\236\158\133\235\139\136\235\139\164.\n\234\179\188\234\177\176, \236\161\176\235\148\148\236\149\133 \235\130\152\236\157\180\236\184\160 \235\130\180\235\182\128\236\151\144\236\132\156 \236\157\188\236\150\180\235\130\156 \236\130\172\234\177\180\236\156\188\235\161\156 \235\140\128\235\182\128\235\182\132\236\157\152 \236\160\132\235\160\165\236\157\132 \236\131\129\236\139\164\237\149\156 \235\160\136\235\147\156 \236\139\156\237\148\132\237\138\184 \236\184\161\236\157\128 \236\131\136\235\161\156\236\154\180 \235\139\168\236\158\165\236\157\132 \236\164\145\236\139\172\236\156\188\235\161\156 \235\139\164\236\139\156\234\184\136 \234\184\176\236\130\172\235\139\168\236\157\132 \236\158\172\234\178\176\236\132\177\237\149\152\236\152\128\236\138\181\235\139\136\235\139\164. \234\183\184\234\178\131\236\157\180 \236\132\164\235\160\185 \235\176\152\236\151\173\236\157\180\235\157\188\234\179\160 \235\182\136\235\166\172\235\138\148 \237\150\137\236\156\132\236\157\188\236\167\128\235\157\188\235\143\132, \234\183\184\235\147\164\236\151\144\234\178\140 \236\158\136\236\150\180 \236\164\145\236\154\148\237\149\156 \234\178\131\236\157\128 \237\151\136\236\154\184\235\191\144\236\157\184 \234\176\128\235\172\184\234\179\188 \234\182\140\236\156\132\234\176\128 \236\149\132\235\139\140, \236\132\184\236\131\129\236\157\152 \236\167\136\236\132\156\235\165\188 \235\176\148\235\161\156\236\158\161\236\157\132 \237\158\152\236\157\152 \235\133\188\235\166\172\236\152\128\234\184\176 \235\149\140\235\172\184\236\158\133\235\139\136\235\139\164. \235\143\153\236\139\156\236\151\144 \234\183\184\235\147\164\236\157\152 \236\161\180\236\158\172\234\176\128 \234\179\167 \235\179\132\235\185\155\236\157\180 \234\183\184\235\147\164\236\157\132 \236\157\184\236\160\149\237\150\136\235\139\164\235\138\148 \235\156\187\236\157\180\234\184\176\235\143\132 \237\149\169\235\139\136\235\139\164.\n\236\149\132\236\133\128\235\157\188 \235\152\144\237\149\156 \235\139\164\235\165\184 \235\160\136\235\147\156 \236\139\156\237\148\132\237\138\184\236\157\152 \236\157\188\236\155\144\235\147\164\234\179\188 \235\167\136\236\176\172\234\176\128\236\167\128\235\161\156 \236\149\140\235\160\164\236\167\132 \234\176\156\236\157\184 \236\160\149\235\179\180\235\138\148 \234\183\184\235\166\172 \235\167\142\236\167\128 \236\149\138\236\138\181\235\139\136\235\139\164. \237\149\152\236\167\128\235\167\140 \236\151\180\235\145\144 \234\176\128\235\172\184 \236\134\140\236\134\141\236\157\180 \236\149\132\235\139\140, \237\149\152\235\172\188\235\169\176 \234\184\176\236\130\172\235\143\132\236\153\128\235\138\148 \234\177\176\235\166\172\234\176\128 \235\168\188 \234\183\184\235\133\128\234\176\128 \235\179\132\236\157\152 \235\172\180\234\181\172\235\165\188 \235\139\164\235\163\176 \236\136\152 \236\158\136\235\139\164\235\138\148 \234\178\131\236\157\128 \235\170\133\235\176\177\237\149\156 \236\130\172\236\139\164\236\158\133\235\139\136\235\139\164. \235\139\164\236\139\156 \235\167\144\237\149\180, \234\183\184\235\133\128\236\157\152 \234\177\176\235\140\128\237\149\156 \234\176\128\236\156\132\234\176\128 \234\178\176\234\181\173\236\151\144\235\138\148 \234\176\128\236\167\156\236\151\144 \236\167\128\235\130\152\236\167\128 \236\149\138\236\157\128 \235\172\188\234\177\180\236\157\180\235\157\188\234\179\160 \237\149\160\236\167\128\235\157\188\235\143\132, \234\183\184 \236\189\148\236\150\180\234\176\128 \235\144\152\235\138\148 \235\179\132\235\185\155\236\157\128 \237\139\