L12_1 = "\235\175\188\237\149\152\235\138\148 \236\154\176\235\143\132\235\176\169\236\157\180\235\157\188\235\138\148 \235\143\133\237\138\185\237\149\156 \236\139\172\236\139\160\236\136\152\235\160\168\235\178\149\236\157\132 \234\177\176\236\185\156 \236\185\180\236\154\180\237\132\176 \236\164\145 \237\149\156 \235\170\133\236\158\133\235\139\136\235\139\164. \234\183\184\235\133\128\235\138\148 \236\138\164\236\138\185 \237\131\156\236\156\160\235\140\128\236\130\172\235\165\188 \236\149\132\235\178\132\236\167\128\236\178\152\235\159\188 \235\148\176\235\158\144\236\156\188\235\130\152, \234\183\184\236\157\152 \234\176\145\236\158\145\236\138\164\235\159\176 \236\163\189\236\157\140 \236\157\180\237\155\132 \234\183\184\235\157\188\236\154\180\235\147\156 \236\155\144\236\157\152 \234\179\181\236\157\184\236\185\180\236\154\180\237\132\176\235\157\188\235\138\148 \235\172\180\234\177\176\236\154\180 \236\167\129\236\177\133\236\157\132 \236\157\180\236\150\180 \235\176\155\234\178\140 \235\144\144\236\138\181\235\139\136\235\139\164. \237\149\152\236\167\128\235\167\140 \236\177\133\236\158\132\234\176\144\235\179\180\235\139\168 \235\179\181\236\136\152\236\139\172\236\157\180 \236\149\158\236\132\176\235\141\152 \234\183\184\235\133\128\235\138\148 \236\167\129\236\177\133\236\157\132 \235\172\180\236\139\156\237\149\152\234\179\160 \234\183\184\235\157\188\236\154\180\235\147\156 \236\155\144\236\157\132 \235\150\160\235\130\152 \236\138\164\236\138\185\236\157\132 \236\130\180\237\149\180\237\149\156 \236\158\144\235\165\188 \236\176\190\236\149\132 \236\152\168 \236\132\184\236\131\129\236\157\132 \235\150\160\235\143\132\235\138\148 \236\164\145\236\158\133\235\139\136\235\139\164.\n\234\183\184\235\159\176 \234\183\184\235\133\128\236\157\152 \236\163\188\235\179\128 \237\143\137\237\140\144\236\157\128 \235\179\181\236\136\152\234\183\128\236\185\152\234\179\160 \234\189\164 \234\184\141\236\160\149\236\160\129\236\157\184 \237\142\184\236\158\133\235\139\136\235\139\164. \236\185\168\236\139\157\236\158\172\235\130\156 \235\149\140\235\167\136\235\139\164 \235\167\142\236\157\128 \236\130\172\235\158\140\235\147\164\236\157\132 \234\181\172\237\149\152\234\179\160 \236\156\160\236\156\160\237\158\136 \236\130\172\235\157\188\236\161\140\235\139\164\235\138\148 \236\157\188\237\153\148\234\176\128 \236\132\184\236\131\129 \234\179\179\234\179\179\236\151\144 \235\130\168\236\149\132\236\158\136\236\163\160.\n\236\151\172\234\184\176\236\151\148 \234\183\184\235\133\128 \236\138\164\236\138\185\236\157\152 \235\143\133\237\138\185\237\149\156 \236\136\152\235\160\168\235\178\149\236\157\180 \236\152\129\237\150\165\236\157\132 \236\164\128 \234\178\131\236\156\188\235\161\156 \235\179\180\236\158\133\235\139\136\235\139\164. \234\183\184 \234\176\128\235\165\180\236\185\168 \235\149\140\235\172\184\236\151\144 \234\179\164\234\182\129\236\151\144 \236\178\152\237\149\156 \236\130\172\235\158\140\236\157\132 \235\179\180\235\169\180 \235\172\180\236\139\156\237\149\152\236\167\128 \235\170\187\237\149\152\234\179\160, \234\176\144\236\130\172\235\165\188 \235\176\155\236\157\132 \235\149\144 \237\157\172\236\151\180\236\157\132 \235\138\144\235\129\188\235\138\148 \235\167\136\236\157\140\236\157\132 \237\131\128\234\179\160\235\130\152\235\178\132\235\166\176 \234\178\131\236\157\180\236\163\160.\n\235\175\188\237\149\152\235\138\148 \236\157\180\235\159\176 \236\158\144\236\139\160\236\157\152 \236\132\177\234\178\169\236\151\144 \235\178\136\234\177\176\235\161\156\236\155\128\236\157\132 \235\138\144\235\129\188\236\167\128\235\167\140, \235\139\185\236\158\165 \235\130\180\236\157\188\235\143\132 \235\136\132\234\181\176\234\176\128 \236\158\144\236\139\160\236\157\132 \237\149\132\236\154\148\235\161\156 \237\149\156\235\139\164\235\169\180 \235\179\181\236\136\152\235\138\148 \236\160\145\236\150\180\235\145\144\234\179\160 \235\143\132\236\155\128\236\157\132 \236\164\132 \234\178\131\236\158\133\235\139\