L37_1 = "\235\130\152\237\131\136\235\166\172\236\149\132 \235\166\172\236\134\140\235\176\148\235\138\148 \236\130\180\236\157\132 \236\151\144\235\138\148 \237\152\185\237\149\156 \236\167\128\235\140\128\236\157\152 \235\182\129\235\176\169\237\149\169\236\157\152\236\178\180 \236\182\156\236\139\160\236\157\180\236\167\128\235\167\140, \235\148\176\235\156\187\237\149\156 \236\139\172\236\132\177\236\157\132 \234\176\128\236\167\132 \236\178\156\236\167\132\235\130\156\235\167\140\237\149\156 \236\134\140\235\133\128\236\158\133\235\139\136\235\139\164. \235\185\132\235\161\157 \236\158\133\235\179\180\235\139\164 \236\157\152\236\154\149\236\157\180 \236\149\158\236\132\156 \236\158\144\236\163\188 \235\167\144\236\157\132 \235\141\148\235\147\172\236\167\128\235\167\140, \236\152\164\237\158\136\235\160\164 \236\163\188\235\179\128\236\157\184\235\147\164\236\151\144\234\178\140 \234\183\128\236\151\172\236\155\128 \235\176\155\234\184\176\235\143\132 \237\149\169\235\139\136\235\139\164.\n\234\184\176\234\179\132\236\153\128 \234\179\181\235\170\133\237\149\152\235\138\148 \235\138\165\235\160\165\236\157\132 \234\176\128\236\167\132 \235\130\152\237\131\136\235\166\172\236\149\132\235\138\148 \234\183\184\235\133\128\234\176\128 \236\167\129\236\160\145 \236\160\156\236\158\145\237\149\156 \235\161\156\235\180\135 \236\151\172\236\154\176, \237\143\173\236\139\164\236\157\180\236\153\128 \237\149\173\236\131\129 \237\149\168\234\187\152\237\149\152\235\169\176, \236\181\156\236\178\168\235\139\168 \234\184\176\235\138\165\236\157\180 \237\131\145\236\158\172\235\144\156 \237\143\173\236\139\164\236\157\180\235\138\148 \236\149\132\236\167\129 \236\150\180\235\166\176 \235\130\152\237\131\136\235\166\172\236\149\132\234\176\128 \237\149\180\234\178\176\237\149\152\236\167\128 \235\170\187\237\149\152\235\138\148 \235\140\128\235\182\128\235\182\132\236\157\152 \235\172\184\236\160\156\235\165\188 \235\138\160\235\166\132\237\149\152\234\178\140 \237\149\180\234\178\176\237\149\169\235\139\136\235\139\164.\n\236\181\156\234\183\188 \235\182\129\235\176\169\237\149\169\236\157\152\236\178\180\236\157\152 \236\180\157\236\176\184\235\170\168\236\158\165 \237\142\160\235\166\173\236\138\164\236\153\128 \234\179\181\236\139\157 \236\132\157\236\131\129\236\151\144 \235\143\153\237\150\137\237\149\152\235\138\148 \235\170\168\236\138\181\236\157\180 \236\151\172\235\159\172 \235\178\136 \235\170\169\234\178\169\235\144\152\236\151\136\234\184\176\236\151\144, \236\157\188\234\176\129\236\151\144\236\132\156\235\138\148 \236\150\180\235\166\176 \236\149\132\236\157\180\236\157\152 \236\157\180\235\175\184\236\167\128\235\165\188 \236\160\149\236\185\152 \236\136\152\235\139\168\236\156\188\235\161\156 \236\130\172\236\154\169\237\149\156\235\139\164\235\138\148 \235\185\132\235\130\156 \236\151\172\235\161\160\236\157\180 \236\158\136\236\151\136\236\167\128\235\167\140, \236\157\180\236\151\144 \234\180\128\237\149\180 \237\142\160\235\166\173\236\138\164 \236\184\161\236\157\128 \236\150\180\235\150\164 \236\158\133\236\158\165\235\143\132 \235\176\157\237\158\136\236\167\128 \236\149\138\236\149\152\236\138\181\235\139\136\235\139\164.\n\234\183\184\236\160\128 \236\150\184\236\160\156\235\130\152\236\178\152\235\159\188, \236\150\180\235\166\176 \236\134\140\235\133\128\236\151\144\234\178\140 \235\170\168\237\152\184\237\149\156 \235\175\184\236\134\140\235\165\188 \236\167\128\236\157\132 \235\191\144."
