L39_1 = "\235\169\148\235\166\172 \237\129\172\235\163\168\235\138\148 \237\148\132\235\161\160\237\138\184 \235\178\160\236\157\180\236\157\152 \235\170\133\235\172\184\234\176\128, \237\129\172\235\163\168 \234\176\128\235\172\184\236\157\152 \236\149\136\236\163\188\236\157\184\236\158\133\235\139\136\235\139\164.\n\234\183\184\235\133\128\235\138\148 \235\143\153\235\182\128 \237\149\180\234\178\189 \236\130\172\235\160\185\234\180\128\236\157\152 \235\130\180\236\161\176\236\151\144 \237\158\152\236\147\176\235\138\148 \236\149\132\235\130\180\236\157\180\236\158\144, \236\132\184 \236\158\144\235\167\164\236\157\152 \236\151\132\234\178\169\237\149\156 \236\150\180\235\168\184\235\139\136\235\161\156 \236\149\140\235\160\164\236\160\184 \236\158\136\236\163\160. \235\152\144\237\149\156, \236\134\144\236\151\144 \235\172\188 \237\149\156 \235\178\136 \236\149\136 \235\172\187\237\152\148\236\157\132 \234\178\131 \234\176\153\236\157\128 \236\153\184\235\170\168\234\179\188\235\138\148 \235\139\172\235\166\172 \236\151\172\235\159\172 \234\179\160\235\144\156 \236\157\188\236\151\144 \235\130\152\236\132\156 \236\134\148\236\132\160\236\136\152\235\178\148\237\149\152\235\138\148 \235\170\168\236\138\181\236\157\132 \236\151\172\235\159\172\235\178\136 \235\179\180\236\151\172\236\163\188\236\150\180 \235\133\184\235\184\148\235\160\136\236\138\164 \236\152\164\235\184\148\235\166\172\236\163\188\235\165\188 \236\139\164\236\178\156\237\149\152\235\138\148 \234\183\128\235\182\128\236\157\184\236\156\188\235\161\156\235\143\132 \236\156\160\235\170\133\237\149\169\235\139\136\235\139\164. \237\149\152\236\167\128\235\167\140 \236\157\180\235\159\176 \234\183\184\235\133\128\235\165\188 \236\167\136\237\136\172\237\149\152\235\138\148 \236\130\172\235\158\140\235\147\164\236\157\128 \236\158\136\234\184\176 \235\167\136\235\160\168, \235\169\148\235\166\172 \237\129\172\235\163\168\234\176\128 \236\130\172\236\139\164\236\157\128 \236\149\133\235\170\133 \235\13